          back = back + pBackText

        back = back + pBackText[0:backTextRemain]

        if 'l' == pAlignment :
          result = result + back

        elif 'c' == pAlignment :
          result = back[0:(len(back)/2)] + result + back[(len(back)/2):]

        elif 'r' == pAlignment :
          result = back + result

    except Exception, e:
      result = pText

